import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import {
  HEARTBEAT_FRESH_MS,
  HEARTBEAT_ID,
  migrate,
  nowIso,
  openDatabase,
  toJob,
  transaction,
  type Job,
  type JobRow,
} from './db.ts';

const db = openDatabase();
migrate(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 1024 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error }, headers);
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isInteger(v: unknown): v is number {
  return typeof v === 'number' && Number.isInteger(v);
}

/** Reads the whole body, but stops buffering past the cap (the body is still drained). */
function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!tooLarge) chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function getJobRow(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

function handleHealth(res: ServerResponse): void {
  const row = db.prepare('SELECT beat_ms FROM worker_heartbeat WHERE id = ?').get(HEARTBEAT_ID) as
    | { beat_ms: number }
    | undefined;
  const up = row !== undefined && Date.now() - Number(row.beat_ms) < HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(toJob) });
}

function handleGetJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'Job not found');
    return;
  }
  const row = getJobRow(id);
  if (!row) {
    sendError(res, 404, 'not_found', 'Job not found');
    return;
  }
  send(res, 200, toJob(row));
}

type CreateResult = { kind: 'created' | 'replay'; job: Job } | { kind: 'conflict' };

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const fields: FieldError[] = [];
  const bodyError: FieldError = { field: 'body', message: 'Body must be a JSON object' };

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const contentTypeOk = mediaType === 'application/json';
  if (!contentTypeOk) fields.push({ field: 'body', message: 'Content-Type must be application/json' });

  let idempotencyKey: string | null = null;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    if (IDEMPOTENCY_KEY_RE.test(keyHeader)) idempotencyKey = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;

  if (contentTypeOk) {
    let parsed: unknown;
    let parsedOk = false;
    if (!tooLarge) {
      try {
        parsed = JSON.parse(text);
        parsedOk = true;
      } catch {
        parsedOk = false;
      }
    }
    if (tooLarge || !parsedOk || !isPlainObject(parsed)) {
      fields.push(bodyError);
    } else {
      for (const key of Object.keys(parsed)) {
        if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field' });
      }

      if (!Object.hasOwn(parsed, 'input')) {
        fields.push({ field: 'input', message: 'input is required' });
      } else {
        const v = parsed.input;
        if (typeof v !== 'string') fields.push({ field: 'input', message: 'input must be a string' });
        else if (v.length < 1 || v.length > 1000) fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
        else if (v.trim() === '') fields.push({ field: 'input', message: 'input must not be blank' });
        else input = v;
      }

      if (Object.hasOwn(parsed, 'steps')) {
        const v = parsed.steps;
        if (isInteger(v) && v >= 1 && v <= 20) steps = v;
        else fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
      }

      if (Object.hasOwn(parsed, 'failAttempts')) {
        const v = parsed.failAttempts;
        if (isInteger(v) && v >= 0 && v <= 5) failAttempts = v;
        else fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
      }
    }
  }

  if (fields.length > 0) {
    sendError(res, 400, 'invalid_request', 'Invalid request', fields);
    return;
  }

  // Canonical payload after defaults, with a fixed key order, for idempotency comparison.
  const payload = JSON.stringify({ input, steps, failAttempts });

  const result = transaction(db, (): CreateResult => {
    if (idempotencyKey !== null) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as
        | JobRow
        | undefined;
      if (existing) {
        return existing.payload === payload
          ? { kind: 'replay', job: toJob(existing) }
          : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                         created_at, updated_at, run_after, idempotency_key, payload)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
    ).run(id, input, steps, failAttempts, now, now, idempotencyKey, payload);
    return { kind: 'created', job: toJob(getJobRow(id)!) };
  });

  if (result.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload');
  } else if (result.kind === 'replay') {
    send(res, 200, result.job);
  } else {
    send(res, 201, result.job);
  }
}

const jobIdPath = /^\/api\/jobs\/([^/]+)$/;

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const idMatch = jobIdPath.exec(pathname);

  let allowed: string[] | null = null;
  if (pathname === '/' || pathname === '/health' || idMatch) allowed = ['GET'];
  else if (pathname === '/api/jobs') allowed = ['GET', 'POST'];

  if (allowed === null) {
    sendError(res, 404, 'not_found', `No route for ${pathname}`);
    return;
  }
  if (!allowed.includes(method)) {
    sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${pathname}`, undefined, {
      allow: allowed.join(', '),
    });
    return;
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
  } else if (pathname === '/health') {
    handleHealth(res);
  } else if (pathname === '/api/jobs') {
    if (method === 'GET') handleList(res);
    else await handleCreate(req, res);
  } else {
    handleGetJob(res, idMatch![1]!);
  }
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error');
    else res.end();
  });
}).listen(port, () => console.log(`server listening on ${port}`));

function exit(): void {
  try {
    db.close();
  } catch {
    // already closed
  }
  process.exit(0);
}

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(exit);
  server.closeAllConnections();
  setTimeout(exit, 2000);
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

