        if (typeof v !== 'string') fields.push({ field: 'input', message: 'input must be a string' });
        else if (v.length < 1 || v.length > 1000) fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
        else if (v.trim() === '') fields.push({ field: 'input', message: 'input must not be blank' });
        else input = v;
      }

      if (Object.hasOwn(parsed, 'steps')) {
        const v = parsed.steps;
        if (isInteger(v) && v >= 1 && v <= 20) steps = v;
        else fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
      }

      if (Object.hasOwn(parsed, 'failAttempts')) {
        const v = parsed.failAttempts;
        if (isInteger(v) && v >= 0 && v <= 5) failAttempts = v;
