    sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload');
  } else if (result.kind === 'replay') {
    send(res, 200, result.job);
  } else {
    send(res, 201, result.job);
  }
}

const jobIdPath = /^\/api\/jobs\/([^/]+)$/;

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const idMatch = jobIdPath.exec(pathname);

  let allowed: string[] | null = null;
  if (pathname === '/' || pathname === '/health' || idMatch) allowed = ['GET'];
  else if (pathname === '/api/jobs') allowed = ['GET', 'POST'];

  if (allowed === null) {
    sendError(res, 404, 'not_found', `No route for ${pathname}`);
    return;
  }
  if (!allowed.includes(method)) {
    sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${pathname}`, undefined, {
      allow: allowed.join(', '),
    });
    return;
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
  } else if (pathname === '/health') {
    handleHealth(res);
  } else if (pathname === '/api/jobs') {
    if (method === 'GET') handleList(res);
    else await handleCreate(req, res);
  } else {
    handleGetJob(res, idMatch![1]!);
  }
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error');
    else res.end();
  });
}).listen(port, () => console.log(`server listening on ${port}`));

function exit(): void {
  try {
    db.close();
  } catch {
    // already closed
  }
  process.exit(0);
}

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(exit);
  server.closeAllConnections();
  setTimeout(exit, 2000);
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

