import { setTimeout as sleep } from 'node:timers/promises';
import { HEARTBEAT_ID, migrate, nowIso, openDatabase, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const IDLE_POLL_MS = 200;

const db = openDatabase();
migrate(db);

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, beat_ms) VALUES (?, ?)
     ON CONFLICT(id) DO UPDATE SET beat_ms = excluded.beat_ms`,
  ).run(HEARTBEAT_ID, Date.now());
}

heartbeat();
const heartbeatTimer = setInterval(heartbeat, 1000);

/** Puts a job back in the queue after its running attempt was interrupted by a stop or crash. */
function requeue(id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(nowIso(), id);
}

// Crash recovery: this is the only worker, so any job still marked running was orphaned.
// Its interrupted attempt stays counted in `attempts`, as the spec defines attempts as started.
db.prepare(
  `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ?
   WHERE status = 'running'`,
).run(nowIso());

/** Atomically takes the oldest due queued job and marks it running for a new attempt. */
function claim(): JobRow | null {
  return transaction(db, () => {
    const row = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1`)
      .get(Date.now()) as JobRow | undefined;
    if (!row) return null;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
       WHERE id = ? AND status = 'queued'`,
    ).run(nowIso(), row.id);
    return db.prepare('SELECT * FROM jobs WHERE id = ?').get(row.id) as unknown as JobRow;
  });
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: the first step fails before any progress is recorded.
    await sleep(STEP_MS);
    if (stopping) return requeue(job.id);
    if (attempt >= MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ).run(nowIso(), job.id);
    } else {
      db.prepare(
        `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ).run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    }
    return;
  }

  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) return requeue(job.id);
    db.prepare(
      `UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
    ).run(i, nowIso(), job.id);
  }

  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = steps, error = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(job.input.toUpperCase(), nowIso(), job.id);
}

console.log('worker started');

while (!stopping) {
  let job: JobRow | null;
  try {
    job = claim();
  } catch (err) {
    console.error('claim failed:', err);
    await sleep(IDLE_POLL_MS);
    continue;
  }
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (err) {
    console.error(`attempt on job ${job.id} failed:`, err);
    try {
      requeue(job.id);
    } catch {
      // database unavailable; crash recovery on the next start will pick the job up
    }
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.close();
process.exit(0);

